def populate_existing_drive_codes(apps, schema_editor):
    Drive = apps.get_model('assessments', 'Drive')
    import random
    existing_codes = set(Drive.objects.exclude(drive_code__isnull=True).values_list('drive_code', flat=True))
    for drive in Drive.objects.filter(drive_code__isnull=True):
        for _ in range(200):
            cand = str(random.randint(10000000, 99999999))
            if cand not in existing_codes:
                drive.drive_code = cand
                existing_codes.add(cand)
                drive.save(update_fields=['drive_code'])
                break


